package com.fasterxml.jackson.databind.util;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.base.ParserMinimalBase;
import com.fasterxml.jackson.core.json.JsonReadContext;
import com.fasterxml.jackson.core.json.JsonWriteContext;
import com.fasterxml.jackson.core.util.ByteArrayBuilder;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.util.TokenBuffer;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import java.util.TreeMap;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for TokenBuffer.writeNumber(BigDecimal).
 */
public class TokenBuffer_writeNumber_TriageGen1Test {

    private TokenBuffer tokenBuffer;
    private ObjectMapper mapper;

    @Before
    public void setUp() {
        mapper = new ObjectMapper();
        tokenBuffer = new TokenBuffer(mapper);
    }

    @Test
    public void testWriteNumber_WithNull() throws IOException {
        // Test the branch where dec == null
        tokenBuffer.writeNumber((BigDecimal) null);

        assertEquals(JsonToken.VALUE_NULL, tokenBuffer.firstToken());
    }

    @Test
    public void testWriteNumber_WithPositiveBigDecimal() throws IOException {
        // Test the branch where dec != null
        BigDecimal dec = new BigDecimal("123.456");
        tokenBuffer.writeNumber(dec);

        assertEquals(JsonToken.VALUE_NUMBER_FLOAT, tokenBuffer.firstToken());

        // Verify content by serializing to string
        String json = tokenBuffer.toString();
        assertEquals("123.456", json);
    }

    @Test
    public void testWriteNumber_WithZero() throws IOException {
        BigDecimal dec = BigDecimal.ZERO;
        tokenBuffer.writeNumber(dec);

        assertEquals(JsonToken.VALUE_NUMBER_FLOAT, tokenBuffer.firstToken());
        assertEquals("0", tokenBuffer.toString());
    }

    @Test
    public void testWriteNumber_WithNegative() throws IOException {
        BigDecimal dec = new BigDecimal("-0.001");
        tokenBuffer.writeNumber(dec);

        assertEquals(JsonToken.VALUE_NUMBER_FLOAT, tokenBuffer.firstToken());
        assertEquals("-0.001", tokenBuffer.toString());
    }

    @Test
    public void testWriteNumber_WithLargeScale() throws IOException {
        // Test precision handling
        BigDecimal dec = new BigDecimal("1.0000000000000000000000000000001");
        tokenBuffer.writeNumber(dec);

        assertEquals(JsonToken.VALUE_NUMBER_FLOAT, tokenBuffer.firstToken());
        assertEquals("1.0000000000000000000000000000001", tokenBuffer.toString());
    }
}
